#include <stdbool.h>
#include <string.h>

#define MAX_CHARS 10
#define MAX_WORDS 5
#define MAX_LEN 7

typedef struct {
    char words[MAX_WORDS][MAX_LEN+1];
    int wordsCount;
    char result[MAX_LEN+1];
} Equation;

static char chars[MAX_CHARS];        // distinct characters
static int charCount;
static int charToDigit[26];          // map char to digit, -1 if unassigned
static bool usedDigits[10];          // which digits are used
static bool leadingZero[26];         // if char cannot be zero (leading char)
static int wordsCount;
static char words[MAX_WORDS][MAX_LEN+1];
static char result[MAX_LEN+1];

// For fast access: store the length of each word and result
static int wordsLen[MAX_WORDS];
static int resultLen;

// Backtracking function to assign digits to chars
// pos: index of current char to assign
// Returns true if a valid assignment found
static bool backtrack(int pos) {
    if (pos == charCount) {
        // All chars assigned, check if sum matches
        // We'll sum words and compare to result digit by digit from right to left

        int carry = 0;
        int maxLen = resultLen;
        for (int i = 0; i < wordsCount; i++) {
            if (wordsLen[i] > maxLen) maxLen = wordsLen[i];
        }

        for (int i = 0; i < maxLen; i++) {
            int sum = carry;
            // sum digits of words at position i from right
            for (int w = 0; w < wordsCount; w++) {
                int idx = wordsLen[w] - 1 - i;
                if (idx >= 0) {
                    int c = words[w][idx] - 'A';
                    sum += charToDigit[c];
                }
            }
            // digit of result at position i from right
            int ridx = resultLen - 1 - i;
            int rDigit = (ridx >= 0) ? charToDigit[result[ridx] - 'A'] : 0;

            if (sum % 10 != rDigit) return false;
            carry = sum / 10;
        }
        // after all digits, carry must be zero
        return carry == 0;
    }

    int c = chars[pos] - 'A';
    for (int d = 0; d <= 9; d++) {
        if (!usedDigits[d]) {
            if (d == 0 && leadingZero[c]) continue; // leading char cannot be zero
            usedDigits[d] = true;
            charToDigit[c] = d;
            if (backtrack(pos + 1)) return true;
            usedDigits[d] = false;
            charToDigit[c] = -1;
        }
    }
    return false;
}

bool isSolvable(char **wordsInput, int wordsSize, char *resultInput){
    // Initialize global vars
    wordsCount = wordsSize;
    for (int i = 0; i < wordsCount; i++) {
        strcpy(words[i], wordsInput[i]);
        wordsLen[i] = (int)strlen(words[i]);
    }
    strcpy(result, resultInput);
    resultLen = (int)strlen(result);

    // Reset mappings
    memset(charToDigit, -1, sizeof(charToDigit));
    memset(usedDigits, 0, sizeof(usedDigits));
    memset(leadingZero, 0, sizeof(leadingZero));
    charCount = 0;

    // Collect distinct chars
    bool seen[26] = {0};
    for (int i = 0; i < wordsCount; i++) {
        int len = wordsLen[i];
        for (int j = 0; j < len; j++) {
            int c = words[i][j] - 'A';
            if (!seen[c]) {
                seen[c] = true;
                chars[charCount++] = words[i][j];
            }
        }
    }
    int len = resultLen;
    for (int j = 0; j < len; j++) {
        int c = result[j] - 'A';
        if (!seen[c]) {
            seen[c] = true;
            chars[charCount++] = result[j];
        }
    }

    if (charCount > 10) return false; // more than 10 distinct chars impossible

    // Mark leading chars that cannot be zero
    for (int i = 0; i < wordsCount; i++) {
        int c = words[i][0] - 'A';
        leadingZero[c] = true;
    }
    leadingZero[result[0] - 'A'] = true;

    return backtrack(0);
}

